#include "tigersheets/grid.hpp"
#include <QApplication>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
Json fixture(){return Json::parse(R"({"revision":0,"sheets":[{"id":"s","name":"Data","mergedRanges":[{"row1":1,"col1":1,"row2":1,"col2":2}],"cells":[{"row":1,"col":1,"input":"Merged revenue","style":{"bold":true}},{"row":2,"col":1,"input":"2"},{"row":2,"col":2,"input":"20"},{"row":3,"col":1,"input":"1"},{"row":3,"col":2,"input":"10"},{"row":5,"col":1,"input":"Outside"}]}]})");}
void mergedCut(){WorkbookSession session(fixture());WorksheetModel model(session);const auto before=session.snapshot();const auto cut=model.cutRange(0,0,0,1);require(session.snapshot()==before&&!session.canUndo(),"preparing a merged cut retains source data and history");require(!model.pasteRange(0,3,cut),"moving merged cells refuses until merged clipboard authoring is supported");require(model.lastError().contains("Unmerge",Qt::CaseInsensitive)&&session.snapshot()==before&&!session.canUndo(),"refused merged move explains Unmerge first and preserves source, span, destination and undo");}
void copiedMergedSource(){
 for(const auto& coordinates:std::vector<std::array<int,4>>{{0,0,0,1},{0,0,0,0},{0,1,0,1}}){WorkbookSession session(fixture());WorksheetModel model(session);const auto before=session.snapshot();const auto copied=model.copyRange(coordinates[0],coordinates[1],coordinates[2],coordinates[3]);require(copied.value("sourceHasMerges",false),"copy annotates complete or partial merged sources, including hidden interior cells");for(const auto* mode:{"all","formulas","transpose"}){require(!model.pasteRange(0,3,copied,mode)&&model.lastError().contains("Unmerge",Qt::CaseInsensitive),"merged source ordinary, formula and transpose pastes require Unmerge first");require(session.snapshot()==before&&!session.canUndo(),"refused merged copy paste leaves data, spans and history unchanged");}}
 for(const auto* mode:{"values","formats"}){WorkbookSession session(fixture());WorksheetModel model(session);const auto copied=model.copyRange(0,0,0,1);require(model.pasteRange(0,3,copied,mode),"safe Paste Values and Formats remain available from merged sources");require(session.snapshotView()["sheets"][0]["mergedRanges"]==fixture()["sheets"][0]["mergedRanges"],"safe special paste retains source merged layout");if(std::string(mode)=="values")require(model.raw(0,3)=="Merged revenue","Paste Values transfers the merged anchor's literal value");else require(model.raw(0,3).isEmpty()&&model.cellStyle(0,3).at("bold")==true,"Paste Formats transfers styling without hidden values");require(session.undo()&&session.snapshotView()["sheets"]==fixture()["sheets"],"safe special paste is one undoable transaction");}
 WorkbookSession session(fixture());WorksheetModel model(session);require(!model.copyRange(1,0,1,1).value("sourceHasMerges",false),"ordinary copied sources remain unmarked");
}
void mergedDestination(){
 for(const auto* mode:{"all","formulas","values","transpose"}){WorkbookSession session(fixture());WorksheetModel model(session);const auto before=session.snapshot();const auto multiple=model.copyRange(1,0,1,1),single=model.copyRange(1,0,1,0);require(!model.pasteRange(0,0,multiple,mode),"multi-cell value or formula paste overlapping a merged destination refuses");require(model.lastError().contains("Unmerge",Qt::CaseInsensitive)&&session.snapshot()==before&&!session.canUndo(),"multi-cell merged-destination refusal preserves values, span and Undo");require(!model.pasteRange(0,1,single,mode)&&model.lastError().contains("Unmerge",Qt::CaseInsensitive)&&session.snapshot()==before,"single-cell paste into a hidden merged interior refuses");require(model.pasteRange(0,0,single,mode)&&model.raw(0,0)=="2"&&session.snapshotView()["sheets"][0]["mergedRanges"]==before["sheets"][0]["mergedRanges"],"single-cell paste to a merged upper-left anchor remains safe");require(session.undo()&&session.snapshotView()["sheets"]==before["sheets"],"safe anchor paste is one undo transaction");}
 {WorkbookSession session(fixture());WorksheetModel model(session);const auto before=session.snapshot();require(model.pasteRange(0,0,model.copyRange(1,0,1,1),"formats"),"multi-cell Paste Formats remains safe over merged cells");require(model.raw(0,0)=="Merged revenue"&&model.raw(0,1).isEmpty()&&session.snapshotView()["sheets"][0]["mergedRanges"]==before["sheets"][0]["mergedRanges"],"format-only paste preserves merged content and layout");}
 for(const bool multi:{true,false}){WorkbookSession session(fixture());WorksheetModel model(session);const auto before=session.snapshot();const auto cut=model.cutRange(1,0,1,multi?1:0);require(!model.pasteRange(0,multi?0:1,cut)&&model.lastError().contains("Unmerge",Qt::CaseInsensitive)&&session.snapshot()==before&&!session.canUndo(),"cut moves cannot overwrite merged interiors or rectangles");}
 {WorkbookSession session(fixture());WorksheetModel model(session);require(model.pasteRange(0,0,model.cutRange(1,0,1,0))&&model.raw(0,0)=="2"&&model.raw(1,0).isEmpty(),"single-cell cut move to a merged upper-left anchor is supported");require(session.undo()&&session.snapshotView()["sheets"]==fixture()["sheets"],"anchor cut move remains one complete undo");}
}
void mergedSorting(){for(const bool ascending:{true,false})for(const int left:{0,1}){WorkbookSession session(fixture());WorksheetModel model(session);const auto before=session.snapshot();require(!model.sortRange(0,left,2,1,ascending),"sorting complete or partial merged spans refuses");require(model.lastError().contains("Unmerge",Qt::CaseInsensitive)&&session.snapshot()==before&&!session.canUndo(),"merged sort refusal preserves all cells, spans and Undo and explains Unmerge first");}
 WorkbookSession session(fixture());WorksheetModel model(session);require(model.sortRange(1,0,2,1,true)&&model.raw(1,0)=="1"&&model.raw(1,1)=="10"&&model.raw(2,0)=="2"&&model.raw(0,0)=="Merged revenue","sorting an unrelated rectangle remains supported");require(session.undo()&&session.snapshotView()["sheets"]==fixture()["sheets"],"ordinary sorting remains one Undo");model.refresh();require(model.pasteRange(1,3,model.copyRange(1,0,1,1))&&model.raw(1,3)=="2"&&model.raw(1,4)=="20","ordinary copy/paste remains available outside merges");require(session.undo(),"ordinary copy paste supports Undo");model.refresh();require(model.pasteRange(4,3,model.cutRange(4,0,4,0))&&model.raw(4,0).isEmpty()&&model.raw(4,3)=="Outside","ordinary cut move remains available outside merges");require(session.undo()&&session.snapshotView()["sheets"]==fixture()["sheets"],"ordinary cut move remains one Undo");
}
int main(int argc,char** argv){QApplication app(argc,argv);try{mergedCut();copiedMergedSource();mergedDestination();mergedSorting();std::cout<<"merged worksheet edit guards passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
